#include <assert.h>
#include <stdio.h>
#include "preflight.h"
int main(void){unsigned checks=0;assert(!aa_preflight_lookup(0));assert(!aa_preflight_lookup(UINT64_MAX));checks+=2;for(unsigned i=0;i<20;i++){const aa_preflight_entry*p=aa_preflight_lookup(aa_preflight_rows[i].snapshot);assert(p==aa_preflight_rows+i);uint64_t hits[4];for(unsigned j=0;j<4;j++)hits[j]=p->hits[j];assert(aa_preflight_actual_matches(p,hits,aa_preflight_targets[i]));checks++;assert(!aa_preflight_actual_matches(p,hits,aa_preflight_targets[i]+1));checks++;for(unsigned j=0;j<4;j++){hits[j]++;assert(!aa_preflight_actual_matches(p,hits,aa_preflight_targets[i]));hits[j]-=2;assert(!aa_preflight_actual_matches(p,hits,aa_preflight_targets[i]));hits[j]++;checks+=2;}hits[0]++;hits[1]--;assert(!aa_preflight_actual_matches(p,hits,aa_preflight_targets[i]));checks++;}printf("{\"status\":\"PASS\",\"checks\":%u,\"unknownBindingRejected\":true,\"countUpDownRedistributionRejected\":true,\"ROBytes\":%zu}\n",checks,sizeof aa_preflight_rows+sizeof aa_preflight_targets);}
